('de','messages:apihelp-query+allpages-param-prlevel','s:98:\"de:Seitenschutze nach Schutzstufe filtern (muss zusammen mit $1prtype=parameter angegeben werden).\";'),
('de','messages:apihelp-query+allpages-param-prtype','s:36:\"de:Nur geschützte Seiten auflisten.\";'),
('de','messages:apihelp-query+allpages-param-to','s:50:\"de:Seitentitel, bei dem die Auflistung enden soll.\";'),
('de','messages:apihelp-query+allpages-paramvalue-prexpiry-all','s:65:\"de:Geschützte Seiten unabhängig von der Schutzlänge auflisten.\";'),
('de','messages:apihelp-query+allpages-paramvalue-prexpiry-definite','s:67:\"de:Nur für einen bestimmten Zeitraum geschützte Seiten auflisten.\";'),
('de','messages:apihelp-query+allpages-paramvalue-prexpiry-indefinite','s:50:\"de:Nur unbeschränkt geschützte Seiten auflisten.\";'),
('de','messages:apihelp-query+allpages-summary','s:59:\"de:Listet alle Seiten in einem Namensraum nacheinander auf.\";'),
('de','messages:apihelp-query+allredirects-example-b','s:111:\"de:Listet Zielseiten, auch fehlende, mit den Seitenkennungen der Weiterleitung auf, beginnend bei <kbd>B</kbd>.\";'),
('de','messages:apihelp-query+allredirects-example-generator','s:52:\"de:Seiten abrufen, die die Weiterleitungen enthalten\";'),
('de','messages:apihelp-query+allredirects-example-unique','s:37:\"de:Einzigartige Zielseiten auflisten.\";'),
('de','messages:apihelp-query+allredirects-example-unique-generator','s:54:\"de:Bezieht alle Zielseiten und markiert die Fehlenden.\";'),
('de','messages:apihelp-query+allredirects-param-dir','s:24:\"de:Aufzählungsrichtung.\";'),
('de','messages:apihelp-query+allredirects-param-from','s:65:\"de:Titel der Weiterleitung, bei der die Auflistung beginnen soll.\";'),
('de','messages:apihelp-query+allredirects-param-limit','s:45:\"de:Gesamtanzahl der aufzulistenden Einträge.\";'),
('de','messages:apihelp-query+allredirects-param-namespace','s:35:\"de:Der zu untersuchende Namensraum.\";'),
('de','messages:apihelp-query+allredirects-param-prefix','s:72:\"de:Weiterleitungen auflisten, deren Zielseiten mit diesem Wert beginnen.\";'),
('de','messages:apihelp-query+allredirects-param-prop','s:31:\"de:Zu beziehende Informationen:\";'),
('de','messages:apihelp-query+allredirects-param-to','s:62:\"de:Titel der Weiterleitung, bei der die Auflistung enden soll.\";'),
