('de','messages:apihelp-query+allredirects-summary','s:52:\"de:Bezieht alle Weiterleitungen in einem Namensraum.\";'),
('de','messages:apihelp-query+allrevisions-example-ns-any','s:68:\"de:Liste die ersten 50 Versionen in einem beliebigen Namensraum auf.\";'),
('de','messages:apihelp-query+allrevisions-example-user','s:82:\"de:Liste die letzten 50 Beiträge, sortiert nach Benutzer <kbd>Beispiel</kbd> auf.\";'),
('de','messages:apihelp-query+allrevisions-param-end','s:54:\"de:Der Zeitstempel, bei dem die Auflistung enden soll.\";'),
('de','messages:apihelp-query+allrevisions-param-excludeuser','s:67:\"de:Schließe Bearbeitungen dieses Benutzers bei der Auflistung aus.\";'),
('de','messages:apihelp-query+allrevisions-param-generatetitles','s:80:\"de:Wenn als Generator verwendet, werden eher Titel als Bearbeitungs-IDs erzeugt.\";'),
('de','messages:apihelp-query+allrevisions-param-namespace','s:43:\"de:Nur Seiten dieses Namensraums auflisten.\";'),
('de','messages:apihelp-query+allrevisions-param-start','s:57:\"de:Der Zeitstempel, bei dem die Auflistung beginnen soll.\";'),
