('de','messages:apihelp-query+alltransclusions-param-from','s:68:\"de:Der Titel der Transklusion, bei der die Auflistung beginnen soll.\";'),
('de','messages:apihelp-query+alltransclusions-param-limit','s:56:\"de:Wie viele Gesamtobjekte zurückgegeben werden sollen.\";'),
('de','messages:apihelp-query+alltransclusions-param-namespace','s:32:\"de:Der aufzulistende Namensraum.\";'),
('de','messages:apihelp-query+alltransclusions-param-prefix','s:73:\"de:Suche nach allen transkludierten Titeln, die mit diesem Wert beginnen.\";'),
('de','messages:apihelp-query+alltransclusions-param-prop','s:38:\"de:Welche Informationsteile einbinden:\";'),
('de','messages:apihelp-query+alltransclusions-param-to','s:65:\"de:Der Titel der Transklusion, bei der die Auflistung enden soll.\";'),
('de','messages:apihelp-query+alltransclusions-param-unique','s:191:\"de:Zeigt nur eindeutige transkribierte Titel an. Kann nicht mit $1prop=ids verwendet werden.\nWenn es als Generator verwendet wird, werden die Zielseiten anstelle der Ausgangsseiten angezeigt.\";'),
('de','messages:apihelp-query+alltransclusions-paramvalue-prop-ids','s:100:\"de:Fügt die Seiten-ID der transkludierenden Seite hinzu (kann nicht mit $1unique verwendet werden).\";'),
('de','messages:apihelp-query+alltransclusions-paramvalue-prop-title','s:42:\"de:Fügt den Titel der Transklusion hinzu.\";'),
('de','messages:apihelp-query+alltransclusions-summary','s:129:\"de:Liste alle Transklusionen auf (eingebettete Seiten die &#123;&#123;x&#125;&#125; benutzen), einschließlich nicht vorhandener.\";'),
('de','messages:apihelp-query+allusers-example-y','s:38:\"de:Benutzer ab <kbd>Y</kbd> auflisten.\";'),
('de','messages:apihelp-query+allusers-param-activeusers','s:97:\"de:Listet nur Benutzer auf, die {{PLURAL:$1|am letzten Tag|in den letzten $1 Tagen}} aktiv waren.\";'),
