('de','messages:apihelp-query+usercontribs-summary','s:49:\"de:Alle Bearbeitungen von einem Benutzer abrufen.\";'),
('de','messages:apihelp-query+userinfo-example-data','s:67:\"de:Ruft zusätzliche Informationen über den aktuellen Benutzer ab.\";'),
('de','messages:apihelp-query+userinfo-example-simple','s:53:\"de:Informationen über den aktuellen Benutzer abrufen\";'),
