('en','messages:apihelp-feedrecentchanges-param-feedformat','s:26:\"en:The format of the feed.\";'),
('en','messages:apihelp-feedrecentchanges-param-from','s:27:\"en:Show changes since then.\";'),
('en','messages:apihelp-feedrecentchanges-param-hideanons','s:40:\"en:Hide changes made by anonymous users.\";'),
('en','messages:apihelp-feedrecentchanges-param-hideanons-temp','s:63:\"en:Hide changes made by anonymous users and temporary accounts.\";'),
('en','messages:apihelp-feedrecentchanges-param-hidebots','s:29:\"en:Hide changes made by bots.\";'),
('en','messages:apihelp-feedrecentchanges-param-hidecategorization','s:36:\"en:Hide category membership changes.\";'),
('en','messages:apihelp-feedrecentchanges-param-hideliu','s:41:\"en:Hide changes made by registered users.\";'),
