('en','messages:apihelp-query+logevents-paramvalue-prop-timestamp','s:40:\"en:Adds the timestamp for the log event.\";'),
('en','messages:apihelp-query+logevents-paramvalue-prop-title','s:48:\"en:Adds the title of the page for the log event.\";'),
('en','messages:apihelp-query+logevents-paramvalue-prop-type','s:30:\"en:Adds the type of log event.\";'),
